#[summary("example checks for first_in_sorted")]
mod task_test {
    #[effects(pure)]
    #[uses(tasks::x_absent, tasks::x_first_at)]
    fn example_dup() -> (r: i64)
        ensures r == 2,
    {
        let a: [i64; 7] = [3, 4, 5, 5, 5, 5, 6];
        tasks::first_in_sorted(&a, 5)
    }

    #[effects(pure)]
    #[uses(tasks::x_absent, tasks::x_first_at)]
    fn example_missing() -> (r: i64)
        ensures r == -1,
    {
        let a: [i64; 2] = [1, 2];
        tasks::first_in_sorted(&a, 7)
    }
}

