#[summary("first_in_sorted: lowest index where arr[i] == x, else -1")]
mod tasks {
    #[effects(pure)]
    #[uses(x_absent, x_first_at)]
    fn first_in_sorted(arr: &[i64], x: i64) -> (r: i64)
        requires arr.len() <= 9223372036854775807,
        ensures r == -1 ==> x_absent(arr, x), r == -1 || x_first_at(arr, x, r),
    {
        let mut i: usize = 0;
        while i < arr.len() && arr[i] != x
            invariant i <= arr.len(), forall|k: usize| #[trigger] arr[k] == x ==> k >= i,
            decreases arr.len() - i,
        {
            i = i + 1;
        }
        if i < arr.len() {
            i as i64
        } else {
            -1
        }
    }

    spec fn x_absent(arr: &[i64], x: i64) -> bool {
        forall|k: usize| #[trigger] arr[k] == x ==> k >= arr.len()
    }

    spec fn x_first_at(arr: &[i64], x: i64, r: i64) -> bool {
        r >= 0 && r < arr.len() && (forall|j: usize| (j == r ==> #[trigger] arr[j] == x) && (forall|k: usize| #[trigger] arr[k] == x ==> k >= r))
    }

    spec fn x_found(arr: &[i64], x: i64, r: i64) -> bool {
        r >= 0 && r < arr.len() && (forall|k: usize| #[trigger] arr[k] == x ==> k >= r)
    }
}

#[summary("0/1 knapsack: max total value of a subset of items with total weight at most capacity")]
mod tasks {
    spec fn best(i: usize, w: usize, weights: &[i64], values: &[i64]) -> i64
        decreases i,
    {
        if i == 0 {
            0
        } else {
            let b0: i64 = best(i - 1, w, weights, values);
            let b1: i64 = if weights[i - 1] <= w {
                best(i - 1, w - weights[i - 1], weights, values) + values[i - 1]
            } else {
                b0
            };
            if b0 >= b1 {
                b0
            } else {
                b1
            }
        }
    }

    spec fn best_bounds(i: usize, weights: &[i64], values: &[i64]) -> bool {
        i <= weights.len() && (forall|w: usize| 0 <= #[trigger] best(i, w, weights, values) && best(i, w, weights, values) <= i * 1000000000000000)
    }

    spec fn domain_ok(capacity: usize, weights: &[i64], values: &[i64]) -> bool {
        capacity <= 1000 && items_ok(weights, values)
    }

    spec fn is_opt(r: i64, capacity: usize, weights: &[i64], values: &[i64]) -> bool {
        r == best(weights.len(), capacity, weights, values)
    }

    spec fn items_ok(weights: &[i64], values: &[i64]) -> bool {
        weights.len() == values.len() && weights.len() <= 30 && (forall|j: usize| j < weights.len() ==> 1 <= #[trigger] weights[j] && weights[j] <= 1000 && 0 <= values[j] && values[j] <= 1000000000000000)
    }

    #[effects(pure)]
    #[uses(best, best_bounds, domain_ok, is_opt, items_ok)]
    fn knapsack(capacity: usize, weights: &[i64], values: &[i64]) -> (r: i64)
        requires domain_ok(capacity, weights, values),
        ensures is_opt(r, capacity, weights, values),
    {
        let mut dp: [i64; 1001] = [0; 1001];
        let mut i: usize = 0;
        while i < weights.len()
            invariant 0 <= i && i <= weights.len(), best_bounds(i, weights, values), forall|wp: usize| wp <= capacity ==> #[trigger] dp[wp] == best(i, wp, weights, values),
            decreases weights.len() - i,
        {
            let wt: i64 = weights[i];
            let val: i64 = values[i];
            let wu: usize = wt as usize;
            let mut w: usize = capacity;
            while w >= wu
                invariant w <= capacity, forall|wp: usize| wp <= capacity ==> #[trigger] dp[wp] == (if wp > w { best(i + 1, wp, weights, values) } else { best(i, wp, weights, values) }),
                decreases w - wu,
            {
                let a: i64 = dp[w];
                let b: i64 = dp[w - wu] + val;
                dp[w] = if a >= b {
                    a
                } else {
                    b
                };
                w = w - 1;
            }
            i = i + 1;
        }
        dp[capacity]
    }

    spec fn row_state(i: usize, w: usize, cap: usize, dp: &[i64], weights: &[i64], values: &[i64]) -> bool {
        forall|wp: usize| wp <= cap ==> #[trigger] dp[wp] == (if wp > w { best(i + 1, wp, weights, values) } else { best(i, wp, weights, values) })
    }
}

#[summary("Levenshtein edit distance between two i64 sequences")]
mod tasks {
    #[uses(min3)]
    spec fn ed(a: &[i64], b: &[i64], i: usize, j: usize) -> usize
        decreases i + j,
    {
        if i == 0 {
            j
        } else if j == 0 {
            i
        } else {
            min3(ed(a, b, i - 1, j) + 1, ed(a, b, i, j - 1) + 1, ed(a, b, i - 1, j - 1) + (if a[i - 1] == b[j - 1] { 0 } else { 1 }))
        }
    }

    #[effects(pure)]
    #[uses(is_ed, rec_post, short_enough)]
    fn edit_distance(a: &[i64], b: &[i64]) -> (r: usize)
        requires short_enough(a, b),
        ensures is_ed(a, b, r),
    {
        rec(a, b, a.len(), b.len())
    }

    spec fn in_ab(a: &[i64], b: &[i64], i: usize, j: usize) -> bool {
        i <= a.len() && j <= b.len()
    }

    #[uses(ed)]
    spec fn is_ed(a: &[i64], b: &[i64], r: usize) -> bool {
        r == ed(a, b, a.len(), b.len())
    }

    spec fn min2(x: usize, y: usize) -> usize {
        if x < y {
            x
        } else {
            y
        }
    }

    #[uses(min2)]
    spec fn min3(x: usize, y: usize, z: usize) -> usize {
        min2(min2(x, y), z)
    }

    #[effects(pure)]
    #[uses(ed, in_ab, min2, min3, rec_post)]
    fn rec(a: &[i64], b: &[i64], i: usize, j: usize) -> (r: usize)
        requires in_ab(a, b, i, j),
        ensures rec_post(a, b, i, j, r),
        decreases i + j,
    {
        if i == 0 {
            j
        } else if j == 0 {
            i
        } else {
            let d1: usize = rec(a, b, i - 1, j) + 1;
            let d2: usize = rec(a, b, i, j - 1) + 1;
            let d3: usize = rec(a, b, i - 1, j - 1) + (if a[i - 1] == b[j - 1] { 0 } else { 1 });
            let t: usize = if d1 < d2 {
                d1
            } else {
                d2
            };
            if t < d3 {
                t
            } else {
                d3
            }
        }
    }

    #[uses(ed)]
    spec fn rec_post(a: &[i64], b: &[i64], i: usize, j: usize, r: usize) -> bool {
        r == ed(a, b, i, j) && ed(a, b, i, j) <= i + j
    }

    spec fn short_enough(a: &[i64], b: &[i64]) -> bool {
        a.len() <= 64 && b.len() <= 64
    }
}

#[summary("balanced: true when a ±1 parenthesis sequence is properly nested")]
mod tasks {
    #[effects(pure)]
    #[uses(element_ok, elements_ok, min_prefix, sum_prefix, well_formed)]
    fn balanced(p: &[i64]) -> (r: bool)
        requires p.len() <= 1000, elements_ok(p),
        ensures r == well_formed(p),
    {
        let mut i: usize = 0;
        let mut s: i64 = 0;
        let mut m: i64 = 0;
        while i < p.len()
            invariant i <= p.len(), s == sum_prefix(p, i), m == min_prefix(p, i), s <= i, s >= -i,
            decreases p.len() - i,
        {
            s = s + p[i];
            if s < m {
                m = s;
            }
            i = i + 1;
        }
        m >= 0 && s == 0
    }

    spec fn element_ok(p: &[i64], i: usize) -> bool {
        i < p.len() && (p[i] == 1 || p[i] == -1)
    }

    spec fn elements_ok(p: &[i64]) -> bool {
        forall|i: usize| #[trigger] element_ok(p, i)
    }

    spec fn min_prefix(p: &[i64], n: usize) -> i64
        decreases n,
    {
        if n == 0 {
            0
        } else if sum_prefix(p, n) < min_prefix(p, n - 1) {
            sum_prefix(p, n)
        } else {
            min_prefix(p, n - 1)
        }
    }

    spec fn sum_prefix(p: &[i64], n: usize) -> i64
        decreases n,
    {
        if n == 0 {
            0
        } else {
            sum_prefix(p, n - 1) + p[n - 1]
        }
    }

    spec fn well_formed(p: &[i64]) -> bool {
        min_prefix(p, p.len()) >= 0 && sum_prefix(p, p.len()) == 0
    }
}

#[summary("binomial coefficient C(n, k) (Pascal's triangle), 0 when k > n; n <= 67")]
mod tasks {
    spec fn binom(n: u64, k: u64) -> u64
        decreases n,
    {
        if k > n {
            0
        } else if k == 0 {
            1
        } else {
            binom(n - 1, k - 1) + binom(n - 1, k)
        }
    }

    #[effects(pure)]
    #[uses(binom)]
    fn binomial(n: u64, k: u64) -> (r: u64)
        requires n <= 67,
        ensures r == binom(n, k),
        decreases n,
    {
        if k > n {
            0
        } else if k == 0 {
            1
        } else {
            binomial(n - 1, k - 1) + binomial(n - 1, k)
        }
    }
}
